});

Then('the {string} route is active', function (route) {
  assert.strictEqual(this.window.location.hash, route,
    `Expected route "${route}" to be active, got "${this.window.location.hash}"`);
});

Then('the All filter link has the {string} class', function (className) {
  const links = this.document.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === 'All') {
      assert.ok(links[i].classList.contains(className),
        `Expected All filter link to have class "${className}"`);
      return;
    }
  }
  assert.fail('All filter link not found');
});

Then('the Active filter link has the {string} class', function (className) {
  const links = this.document.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === 'Active') {
      assert.ok(links[i].classList.contains(className),
        `Expected Active filter link to have class "${className}"`);
      return;
    }
  }
  assert.fail('Active filter link not found');
});

Then('the Completed filter link has the {string} class', function (className) {
  const links = this.document.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === 'Completed') {
      assert.ok(links[i].classList.contains(className),
        `Expected Completed filter link to have class "${className}"`);
      return;
    }
  }
  assert.fail('Completed filter link not found');
});

Then('the visible items include {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      // Items should not be hidden (display:none) when visible
      assert.ok(items[i].style.display !== 'none',
        `Expected "${title}" to be visible`);
      return;
    }
  }
  assert.fail(`Expected visible items to include "${title}"`);
});

Then('the visible items do not include {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      // If found, it should be hidden (filtered out)
      if (items[i].style.display === 'none') return;
      assert.fail(`Expected "${title}" to not be visible`);
    }
  }
  // Not found at all is also acceptable
});

const { Given, When, Then } = require('@cucumber/cucumber');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert');

const ROOT = path.resolve(__dirname, '..', '..');

Given('the source file {string} exists', function (filePath) {
  const fullPath = path.join(ROOT, filePath);
  assert.ok(fs.existsSync(fullPath), `Source file not found: ${fullPath}`);
  this.sourceFile = fullPath;
});

When('I search for destructive element-rebuilding patterns', function () {
  const content = fs.readFileSync(this.sourceFile, 'utf8');
  this.foundPatterns = [];

  // Search for while-loop patterns that destroy and rebuild entire element trees
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.includes('while (todoListEl.firstChild)') || line.includes('while (todoCountEl.firstChild)')) {
      this.foundPatterns.push(line.trim());
    }
  }
});

Then('the pattern {string} should not appear in the source', function (pattern) {
  const content = fs.readFileSync(this.sourceFile, 'utf8');
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes(pattern)) {
      assert.fail(`Pattern "${pattern}" found at line ${i + 1}: ${lines[i].trim()}`);
    }
  }
});

// TodoMVC app
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var STORAGE_KEY = 'todos-javascript';

  /* ------------------------------------------------------------------ */
  /*  Persistence                                                       */
  /* ------------------------------------------------------------------ */

  function loadTodos() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        var parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          todoList = parsed;
          // Recover the highest id
          for (var i = 0; i < todoList.length; i++) {
            if (todoList[i].id > idCounter) idCounter = todoList[i].id;
          }
          return;
        }
      }
    } catch (e) { /* ignore */ }
    todoList = [];
  }

  function loadFilter() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY + '_filter');
      if (stored) return stored;
    } catch (e) { /* ignore */ }
    return '';
  }

  function saveFilter(f) {
    localStorage.setItem(STORAGE_KEY + '_filter', f);
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todoList));
  }

  function saveFilter(filter) {
    try {
      if (filter === 'all') {
        localStorage.removeItem(STORAGE_KEY + '_filter');
      } else {
        localStorage.setItem(STORAGE_KEY + '_filter', filter);
      }
    } catch (e) { /* ignore */ }
  }

  var todoList = [];
  var idCounter = 0;
  var currentFilter = 'all';
  loadTodos();

  /* ------------------------------------------------------------------ */
  /*  Routing                                                           */
  /* ------------------------------------------------------------------ */

  function getFilterFromHash() {
    var hash = window.location.hash || '';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function restoreFilter() {
    var saved = loadFilter();
    if (saved && saved !== 'all') {
      currentFilter = saved;
      if (saved === 'active') window.location.hash = '#/active';
      else if (saved === 'completed') window.location.hash = '#/completed';
    } else {
      currentFilter = getFilterFromHash();
    }
  }

  function filterTodos(list, filter) {
    if (filter === 'active') {
      return list.filter(function (t) { return !t.completed; });
    }
    if (filter === 'completed') {
      return list.filter(function (t) { return t.completed; });
    }
    return list;
  }

  /* ------------------------------------------------------------------ */
  /*  DOM refs                                                           */
  /* ------------------------------------------------------------------ */

  var newTodoInput = document.querySelector('.new-todo');
  var todoListEl = document.querySelector('.todo-list');
  var mainEl = document.querySelector('.main');
  var footerEl = document.querySelector('.footer');
  var todoCountEl = document.querySelector('.todo-count');

  /* ------------------------------------------------------------------ */
  /*  Render                                                             */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("the main section is hidden")
   * @planks("the main section is visible")
   * @planks("the footer is hidden")
   * @planks("the footer is visible")
   * @planks("the todo list is empty")
   * @planks("the todo list contains {int} item")
   * @planks("the todo list contains {int} items")
   * @planks("the new item has title {string}")
   * @planks("the new item is not completed")
   * @planks("the new-todo input is cleared")
   * @planks("the todo-count reads {string}")
   * @planks("the clear-completed button is hidden")
   * @planks("the clear-completed button is visible")
   * @planks("I navigate to {string}")
   * @planks("the {string} route is active")
   * @planks("the All filter link has the {string} class")
   * @planks("the Active filter link has the {string} class")
   * @planks("the Completed filter link has the {string} class")
   * @planks("the visible items include {string}")
   * @planks("the visible items do not include {string}")
   */
  function render() {
    var filteredList = filterTodos(todoList, currentFilter);

    // Reconcile the todo list in place: preserve DOM node identity,
    // update existing items, append new ones, remove stale ones.
    var existingMap = {};
    for (var i = 0; i < todoListEl.children.length; i++) {
      var id = todoListEl.children[i].getAttribute('data-id');
      if (id) existingMap[id] = todoListEl.children[i];
    }

    var seenIds = {};

    for (var i = 0; i < filteredList.length; i++) {
      var t = filteredList[i];
      var idStr = String(t.id);
      seenIds[idStr] = true;

      var li = existingMap[idStr];
      if (li) {
        // Update existing element in place
        if (t.completed) {
          li.className = 'completed';
        } else {
          li.className = '';
        }
        var toggle = li.querySelector('.toggle');
        if (toggle) toggle.checked = t.completed;
        var label = li.querySelector('label');
        if (label) label.textContent = t.title;
        var edit = li.querySelector('.edit');
        if (edit) edit.value = t.title;
      } else {
        // Create new element
        li = document.createElement('li');
        if (t.completed) li.className = 'completed';
        li.setAttribute('data-id', t.id);

        var view = document.createElement('div');
        view.className = 'view';

        var toggle = document.createElement('input');
        toggle.className = 'toggle';
        toggle.type = 'checkbox';
        if (t.completed) toggle.checked = true;
        view.appendChild(toggle);

        var label = document.createElement('label');
        label.textContent = t.title;
        view.appendChild(label);

        var destroy = document.createElement('button');
        destroy.className = 'destroy';
        view.appendChild(destroy);

        li.appendChild(view);

        var edit = document.createElement('input');
        edit.className = 'edit';
        edit.value = t.title;
        li.appendChild(edit);

        todoListEl.appendChild(li);
      }
    }

    // Remove stale items
    for (var idStr in existingMap) {
      if (!seenIds[idStr]) {
        existingMap[idStr].parentNode.removeChild(existingMap[idStr]);
      }
    }

    var activeCount = 0;
    for (var j = 0; j < todoList.length; j++) {
      if (!todoList[j].completed) activeCount++;
    }

    var word = activeCount === 1 ? 'item' : 'items';
    // Update the count text in place instead of rebuilding
    var strong = todoCountEl.querySelector('strong');
    if (strong) strong.textContent = String(activeCount);
    var textNode = null;
    for (var k = 0; k < todoCountEl.childNodes.length; k++) {
      if (todoCountEl.childNodes[k].nodeType === 3) {
        textNode = todoCountEl.childNodes[k];
        break;
      }
    }
    if (textNode) {
      textNode.textContent = ' ' + word + ' left';
    } else {
      todoCountEl.appendChild(document.createTextNode(' ' + word + ' left'));
    }

    if (todoList.length === 0) {
      mainEl.style.display = 'none';
      footerEl.style.display = 'none';
    } else {
      mainEl.style.display = 'block';
      footerEl.style.display = 'block';
    }

    var completedCount = todoList.length - activeCount;
    var clearBtn = document.querySelector('.clear-completed');
    if (clearBtn) {
      if (completedCount === 0) {
        clearBtn.style.display = 'none';
      } else {
        clearBtn.style.display = 'block';
      }
    }

    saveTodos();

    // Update filter link selected class
    var links = document.querySelectorAll('.filters a');
    for (var l = 0; l < links.length; l++) {
      links[l].classList.remove('selected');
      var href = links[l].getAttribute('href');
      if ((currentFilter === 'all' && (href === '#/' || href === '#' || href === '')) ||
          (currentFilter === 'active' && href === '#/active') ||
          (currentFilter === 'completed' && href === '#/completed')) {
        links[l].classList.add('selected');
      }
    }
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  }

  /* ------------------------------------------------------------------ */
  /*  New todo                                                           */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I type {string} into the new-todo input and press Enter")
   */
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var title = newTodoInput.value.trim();
    if (title === '') return;
    todoList.push({ id: ++idCounter, title: title, completed: false });
    newTodoInput.value = '';
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Toggle completion                                                  */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I toggle the {string} todo")
   * @planks("the {string} todo is marked completed")
   * @planks("the {string} todo is not completed")
   */
  todoListEl.addEventListener('click', function (e) {
    var toggle = e.target.closest('.toggle');
    if (!toggle) return;
    var li = toggle.closest('li');
    if (!li) return;
    var id = parseInt(li.getAttribute('data-id'), 10);
    for (var i = 0; i < todoList.length; i++) {
      if (todoList[i].id === id) {
        todoList[i].completed = !todoList[i].completed;
        break;
      }
    }
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Toggle all                                                        */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I toggle the mark-all-complete checkbox")
   * @planks("every todo is marked completed")
   * @planks("the mark-all-complete checkbox is checked")
   * @planks("the mark-all-complete checkbox is not checked")
   */
  document.querySelector('.toggle-all').addEventListener('change', function () {
    var allCompleted = true;
    for (var i = 0; i < todoList.length; i++) {
      if (!todoList[i].completed) { allCompleted = false; break; }
    }
    var newState = !allCompleted;
    for (var j = 0; j < todoList.length; j++) {
      todoList[j].completed = newState;
    }
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Destroy (event delegation)                                        */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I click the destroy button for {string}")
   * @planks("the todo list does not contain {string}")
   */
  todoListEl.addEventListener('click', function (e) {
    var btn = e.target.closest('.destroy');
    if (!btn) return;
    var li = btn.closest('li');
    if (!li) return;
    var id = parseInt(li.getAttribute('data-id'), 10);
    for (var i = 0; i < todoList.length; i++) {
      if (todoList[i].id === id) {
        todoList.splice(i, 1);
        break;
      }
    }
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Clear completed                                                   */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I click the clear-completed button")
   */
  document.querySelector('.clear-completed').addEventListener('click', function () {
    todoList = todoList.filter(function (t) { return !t.completed; });
    render();
  });

  /* ------------------------------------------------------------------ */
  /*  Edit mode                                                         */
  /* ------------------------------------------------------------------ */

  /**
   * @planks("I double-click the label of {string}")
   * @planks("the {string} todo is in editing mode")
   * @planks("the edit input is focused")
   * @planks("the edit input value is {string}")
   * @planks("the toggle checkbox is hidden")
   * @planks("the destroy button is hidden")
   * @planks("I type {string} into the edit input and press Enter")
   * @planks("I type {string} into the edit input and blur")
   * @planks("I type {string} into the edit input and press Escape")
   * @planks("the {string} todo is not in editing mode")
   * @planks("the {string} todo exists")
   * @planks("the {string} todo does not exist")
   * @planks("the todo item title is {string}")
   */
  todoListEl.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    li.classList.add('editing');
    // Hide the view, show the edit input (CSS would do this, but happy-dom doesn't apply CSS)
    var view = li.querySelector('.view');
    if (view) view.style.display = 'none';
    var editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.style.display = 'block';
      editInput.value = li.querySelector('label').textContent;
      editInput.focus();
    }
  });

  todoListEl.addEventListener('keydown', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;

    if (e.keyCode === ENTER_KEY) {
      saveEdit(li, editInput);
    } else if (e.keyCode === 27) {
      cancelEdit(li);
    }
  });

  todoListEl.addEventListener('blur', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    saveEdit(li, editInput);
  }, true);

  function cancelEdit(li) {
    li.classList.remove('editing');
    var view = li.querySelector('.view');
    if (view) view.style.display = '';
    var editInput = li.querySelector('.edit');
    if (editInput) editInput.style.display = '';
  }

  function saveEdit(li, editInput) {
    var title = editInput.value.trim();
    var id = parseInt(li.getAttribute('data-id'), 10);
    if (title === '') {
      for (var i = 0; i < todoList.length; i++) {
        if (todoList[i].id === id) {
          todoList.splice(i, 1);
          break;
        }
      }
    } else {
      for (var j = 0; j < todoList.length; j++) {
        if (todoList[j].id === id) {
          todoList[j].title = title;
          break;
        }
      }
    }
    render();
  }

  /* ------------------------------------------------------------------ */
  /*  Initial render                                                     */
  /* ------------------------------------------------------------------ */

  currentFilter = 'all';

  window.addEventListener('hashchange', function () {
    currentFilter = getFilterFromHash();
    saveFilter(currentFilter);
    render();
  });

  restoreFilter();
  // Ensure the hash reflects currentFilter
  if (!window.location.hash || window.location.hash === '') {
    if (currentFilter === 'all') {
      window.location.hash = '#/';
    } else if (currentFilter === 'active') {
      window.location.hash = '#/active';
    } else if (currentFilter === 'completed') {
      window.location.hash = '#/completed';
    }
  }
  render();
}());

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

