const { Given, When, Then } = require('@cucumber/cucumber');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert');

const ROOT = path.resolve(__dirname, '..', '..');

Given('the source file {string} exists', function (filePath) {
  const fullPath = path.join(ROOT, filePath);
  assert.ok(fs.existsSync(fullPath), `Source file not found: ${fullPath}`);
  this.sourceFile = fullPath;
});

When('I search for destructive element-rebuilding patterns', function () {
  const content = fs.readFileSync(this.sourceFile, 'utf8');
  this.foundPatterns = [];

  // Search for while-loop patterns that destroy and rebuild entire element trees
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.includes('while (todoListEl.firstChild)') || line.includes('while (todoCountEl.firstChild)')) {
      this.foundPatterns.push(line.trim());
    }
  }
});

Then('the pattern {string} should not appear in the source', function (pattern) {
  const content = fs.readFileSync(this.sourceFile, 'utf8');
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes(pattern)) {
      assert.fail(`Pattern "${pattern}" found at line ${i + 1}: ${lines[i].trim()}`);
    }
  }
});

